function makeAad(owner: string, name: string): Uint8Array {
  const ownerBytes = new TextEncoder().encode(owner);
  const nameBytes = new TextEncoder().encode(name);
  const aad = new Uint8Array(8 + ownerBytes.length + nameBytes.length);
  const view = new DataView(aad.buffer);
  view.setUint32(0, ownerBytes.length, false);
  view.setUint32(4, nameBytes.length, false);
  aad.set(ownerBytes, 8);
  aad.set(nameBytes, 8 + ownerBytes.length);
  return aad;
}

async function deriveKey(password: string, salt: Uint8Array): Promise<CryptoKey> {
  const enc = new TextEncoder();
  const keyMaterial = await crypto.subtle.importKey(
    "raw",
    enc.encode(password),
    "PBKDF2",
    false,
    ["deriveKey"],
  );
  return crypto.subtle.deriveKey(
    {
      name: "PBKDF2",
      salt,
      iterations: 100_000,
      hash: "SHA-256",
    },
    keyMaterial,
    { name: "AES-GCM", length: 256 },
    false,
    ["encrypt", "decrypt"],
  );
}

